// Apogee service worker: lets the installed app start and run without a network.
//
// What it does, and nothing more:
//   - On install it downloads every file in the precache list (sw-manifest.js,
//     generated by tools/build-sw-manifest.js) into a cache named after the
//     version. All or nothing: if one file cannot be fetched, the install fails
//     and the previous worker and cache stay exactly as they were.
//   - It answers same-origin GET requests for those files from that cache,
//     falling back to the network only if the cache is empty. A request for the
//     app's own page (the scope, or index.html) is answered with the cached
//     index.html. Everything else is left alone for the browser to handle.
//   - A new worker WAITS. It is never activated by itself: it activates only
//     when a page of this app asks it to, after the user clicks Reload on the
//     update banner (the message handler below is the only skipWaiting).
//   - On activate it deletes older caches whose name starts with the prefix
//     below, and no other cache: other sites on this origin share Cache Storage.
//
// It never touches the app's stored data, never caches anything that is not on
// the precache list, and makes no requests except same-origin ones. A test
// (tests/guard.test.js) checks these rules in this file.

importScripts("./sw-manifest.js");

const CACHE_PREFIX = "apogee-precache-";
const { version, files } = self.APOGEE_PRECACHE;
const CACHE_NAME = CACHE_PREFIX + version;

const SCOPE = self.registration.scope; // for example the app's folder, ending in a slash
const absolute = (file) => new URL(file, SCOPE).href;
const PRECACHED = new Set(files.map(absolute));
const INDEX = absolute("./index.html");
// The browser test pages live here. They are never served from the cache, so
// tests always run against the current files, not the installed copy.
const TESTS_PATH = new URL("./tests/", SCOPE).pathname;

const lookupOptions = { cacheName: CACHE_NAME, ignoreVary: true };

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    await caches.delete(CACHE_NAME); // start from an empty cache of exactly this version
    const cache = await caches.open(CACHE_NAME);
    try {
      // addAll stores everything or nothing; "reload" skips the HTTP cache so a
      // stale copy of a file cannot end up in the new version's cache.
      await cache.addAll(files.map((file) => new Request(absolute(file), { cache: "reload" })));
    } catch (error) {
      await caches.delete(CACHE_NAME); // leave no half-made cache behind
      throw error; // the install fails: the old worker and its cache stay in charge
    }
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME) await caches.delete(name);
    }
    // Takes over pages that have no worker yet (the very first install). A new
    // version only gets here after the user's click, which reloads the page.
    await self.clients.claim();
  })());
});

// Only a page of this app, and not a test page, may talk to the worker.
function fromThisApp(source) {
  if (!source || typeof source.url !== "string" || !source.url.startsWith(SCOPE)) return false;
  return !new URL(source.url).pathname.startsWith(TESTS_PATH);
}

self.addEventListener("message", (event) => {
  const message = event.data;
  if (!message || typeof message !== "object" || !fromThisApp(event.source)) return;
  if (message.type === "SKIP_WAITING") {
    self.skipWaiting(); // the one and only activation of a waiting worker, on the user's click
  } else if (message.type === "GET_VERSION" && event.ports && event.ports[0]) {
    event.ports[0].postMessage({ version, fileCount: files.length });
  }
});

// Which page asked for a file? The browser tells us the requesting page's id
// (clientId). That holds for every request the page makes, including modules
// imported by other modules, which all belong to the page's document.
async function isFromTestsPage(clientId) {
  if (!clientId) return false;
  try {
    const client = await self.clients.get(clientId);
    return Boolean(client) && new URL(client.url).pathname.startsWith(TESTS_PATH);
  } catch {
    return false;
  }
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === "navigate") {
    const page = url.origin + url.pathname;
    if (page === SCOPE || page === INDEX) {
      event.respondWith(
        caches.match(INDEX, lookupOptions).then((cached) => cached || fetch(request)),
      );
    } else if (url.href.startsWith(SCOPE) && !url.pathname.startsWith(TESTS_PATH)) {
      // some other page of the app: the network first, the cached app page when offline
      event.respondWith(fetch(request).catch(() => caches.match(INDEX, lookupOptions)));
    }
    return;
  }

  if (!PRECACHED.has(url.href)) return; // not one of ours: the browser handles it

  event.respondWith((async () => {
    if (await isFromTestsPage(event.clientId)) return fetch(request);
    const cached = await caches.match(request, lookupOptions);
    return cached || fetch(request);
  })());
});
